mapper.select:
SELECT c.mng_comp_id AS mngCompId, c.comp_name AS compName, g.status, g.abnormal_coord AS abnormalCoord, g.warn_time AS warnTime, g.fault_code AS faultCode, w.wo_status AS woStatus, d.device_id AS deviceId FROM biz_mng_comp c LEFT JOIN gen_gas_pipe_mon g ON c.mng_comp_id = g.comp_id LEFT JOIN biz_gas_repair_wo w ON g.warn_id = w.warn_id LEFT JOIN sys_mon_device d ON c.mng_comp_id = d.comp_id WHERE 1=1
AND c.dept_code LIKE CONCAT(#{regionShortCode}, '%')
AND g.warn_time >= #{startTime}
AND g.warn_time <= #{endTime}
AND c.comp_name LIKE CONCAT('%', #{facilityType}, '%')
AND g.warn_level = #{warnLevel}
AND g.fault_type = #{faultType}
AND w.wo_status = #{woStatus}
